            caption: "A minimal but standard-compliant ERC-20 skeleton.",
            code: "// SPDX-License-Identifier: MIT\npragma solidity ^0.8.20;\n\ncontract MiniToken {\n    string public name = \"Mini Token\";\n    string public symbol = \"MNT\";\n    uint8  public decimals = 18;\n    uint256 public totalSupply;\n\n    mapping(address => uint256) public balanceOf;\n    mapping(address => mapping(address => uint256)) public allowance;\n\n    event Transfer(address indexed from, address indexed to, uint256 value);\n    event Approval(address indexed owner, address indexed spender, uint256 value);\n\n    constructor(uint256 supply) {\n        totalSupply = supply;\n        balanceOf[msg.sender] = supply;\n        emit Transfer(address(0), msg.sender, supply);\n    }\n\n    function transfer(address to, uint256 v) external returns (bool) {\n        require(balanceOf[msg.sender] >= v, \"insufficient\");\n        balanceOf[msg.sender] -= v;\n        balanceOf[to] += v;\n        emit Transfer(msg.sender, to, v);\n        return true;\n    }\n\n    function approve(address s, uint256 v) external returns (bool) {\n        allowance[msg.sender][s] = v;\n        emit Approval(msg.sender, s, v);\n        return true;\n    }\n\n    function transferFrom(address f, address t, uint256 v) external returns (bool) {\n        require(balanceOf[f] >= v && allowance[f][msg.sender] >= v, \"denied\");\n        allowance[f][msg.sender] -= v;\n        balanceOf[f] -= v;\n        balanceOf[t] += v;\n        emit Transfer(f, t, v);\n        return true;\n    }\n}",
